import{_ as a,o,c as t,a2 as s}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"Verified codes and delivery","description":"","frontmatter":{},"headers":[],"relativePath":"internals/codes.md","filePath":"internals/codes.md"}'),n={name:"internals/codes.md"};function i(r,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="verified-codes-and-delivery" tabindex="-1">Verified codes and delivery <a class="header-anchor" href="#verified-codes-and-delivery" aria-label="Permalink to &quot;Verified codes and delivery&quot;">​</a></h1><p>Suho uses one-time codes for <strong>account recovery</strong> (Arise). A code is an attestation on EAS, issued by the Suho code attester.</p><blockquote><p><strong>Note — transfers no longer use a code.</strong> A large transfer to an unverified address is <em>not</em> gated by a one-time code. Earlier it was, but the guardian minted that code automatically from the same passkey signature that authorized the send, so it added no independent security while appearing to. It was removed. A large unverified send is now gated by the account&#39;s passkey (bound to the exact recipient and amount) plus an explicit hold-to-confirm in the app. See <a href="/docs/using/send.html">Send and the guard</a>. A genuine out-of-band factor for large sends — an emailed code that survives a stolen passkey — is planned as account-level hardening and is deliberately absent until it can be built so nothing bypasses it.</p></blockquote><h2 id="what-a-code-is" tabindex="-1">What a code is <a class="header-anchor" href="#what-a-code-is" aria-label="Permalink to &quot;What a code is&quot;">​</a></h2><p><code>SuhoCodeAttester</code> issues a code as a revocable EAS attestation. The stored value is a hash, not the code itself. The hash is <code>keccak256(subject, domain, code)</code>.</p><p>The domain binds the recovery code to a purpose.</p><ul><li>Recovery: <code>suho.arise:&lt;account&gt;:&lt;newKeyHash&gt;</code></li></ul><p>Because the code hash commits to the domain, a code observed in the mempool is useless for any other account or action. <code>verifyAndConsume</code> checks that the attestation exists, is unrevoked, is unexpired, and is unused, then marks it consumed. Re-issuing for the same subject and domain revokes the old code on chain.</p><h2 id="delivery-—-email-only" tabindex="-1">Delivery — email only <a class="header-anchor" href="#delivery-—-email-only" aria-label="Permalink to &quot;Delivery — email only&quot;">​</a></h2><p>Recovery codes are delivered <strong>out of band, to the account&#39;s recovery email</strong>. There is no public code page: the old <code>/issuer</code> portal is retired (it would have been an account-takeover surface), and its route now returns HTTP 410. Operators watch activity through the token-gated <code>/ops</code> endpoint, which never shows a code or an email.</p><p>The design reason for out-of-band delivery is the whole point: a drainer in the browser cannot produce a code it never received.</p><h2 id="expiry" tabindex="-1">Expiry <a class="header-anchor" href="#expiry" aria-label="Permalink to &quot;Expiry&quot;">​</a></h2><p>Recovery codes last ten minutes. Entering an expired code maps to a plain sentence: &quot;Code expired. Request a fresh one.&quot;</p>',13)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
